using System; using System.Data; using System.Data.SqlClient; using System.Drawing; using System.Drawing.Printing; using System.IO; using System.Text; using System.Windows.Forms; using DAAccess;
namespace Toko_Root_ID {
 internal static class ReportTemplate {
  internal enum ReportKind { Barang, Transaksi }
  private static DataGridView grid; private static DataTable data; private static int printRow; private static string reportTitle;
  public static void Apply(Form form, ReportKind kind) {
   form.SuspendLayout(); form.Controls.Clear(); form.Text=kind==ReportKind.Barang?"Root-ID | Laporan Barang":"Root-ID | Laporan Transaksi"; form.WindowState=FormWindowState.Maximized; form.StartPosition=FormStartPosition.CenterParent; form.BackColor=AppTheme.Background; form.Font=new Font("Segoe UI",9F); reportTitle=kind==ReportKind.Barang?"LAPORAN DATA BARANG":"LAPORAN TRANSAKSI PENJUALAN";
   var header=new Panel{Dock=DockStyle.Top,Height=62,Padding=new Padding(16),BackColor=AppTheme.Surface}; var title=new Label{Text=reportTitle,Dock=DockStyle.Left,Width=430,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",15F,FontStyle.Bold),ForeColor=AppTheme.Text}; var buttons=new FlowLayoutPanel{Dock=DockStyle.Right,Width=320,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};
   var refresh=new Button{Text="Muat Ulang",Width=95,Height=32,Margin=new Padding(4)}; var preview=new Button{Text="Cetak / Preview",Width=115,Height=32,Margin=new Padding(4)}; var export=new Button{Text="Export CSV",Width=90,Height=32,Margin=new Padding(4)}; buttons.Controls.Add(refresh);buttons.Controls.Add(preview);buttons.Controls.Add(export);header.Controls.Add(buttons);header.Controls.Add(title);
   grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,BackgroundColor=AppTheme.Surface,BorderStyle=BorderStyle.None,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoGenerateColumns=true}; var status=new Label{Dock=DockStyle.Bottom,Height=28,Padding=new Padding(12,5,0,0),Text="Laporan siap",ForeColor=AppTheme.Text}; form.Controls.Add(grid);form.Controls.Add(status);form.Controls.Add(header);
   refresh.Click+=(s,e)=>LoadData(kind,status);preview.Click+=(s,e)=>PrintPreview(form);export.Click+=(s,e)=>ExportCsv(form);form.Shown+=(s,e)=>LoadData(kind,status);form.ResumeLayout(true);
  }
  private static void LoadData(ReportKind kind,Label status){try{string view=kind==ReportKind.Barang?"dbo.vwReportBarang":"dbo.vwReportPenjualan";using(var con=new SqlConnection(dbConfiguration.ConnectionString))using(var cmd=new SqlCommand("SELECT * FROM "+view,con))using(var da=new SqlDataAdapter(cmd)){data=new DataTable();da.Fill(data);grid.DataSource=data;status.Text=data.Rows.Count.ToString("N0")+" baris data";}}catch(Exception ex){status.Text="Query laporan belum tersedia atau koneksi gagal.";MessageBox.Show("Tidak dapat memuat laporan. Jalankan Database/ERP_POS_Views_Procedures.sql terlebih dahulu.\r\n\r\n"+ex.Message,"Laporan",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
  private static void PrintPreview(IWin32Window owner){if(data==null||data.Rows.Count==0){MessageBox.Show(owner,"Tidak ada data untuk dicetak.");return;}var doc=new PrintDocument();doc.DocumentName=reportTitle;doc.DefaultPageSettings.Landscape=true;doc.BeginPrint+=(s,e)=>printRow=0;doc.PrintPage+=PrintPage;using(var dlg=new PrintPreviewDialog{Document=doc,Width=1000,Height=700})dlg.ShowDialog(owner);}
  private static void PrintPage(object sender,PrintPageEventArgs e){float x=e.MarginBounds.Left,y=e.MarginBounds.Top;using(var tf=new Font("Segoe UI",14,FontStyle.Bold))using(var hf=new Font("Segoe UI",8,FontStyle.Bold))using(var bf=new Font("Segoe UI",8))using(var pen=new Pen(Color.Gray)){e.Graphics.DrawString(reportTitle,tf,Brushes.Black,x,y);y+=32;e.Graphics.DrawString("Dicetak: "+DateTime.Now.ToString("dd-MM-yyyy HH:mm"),bf,Brushes.Black,x,y);y+=24;float w=Math.Max(60,e.MarginBounds.Width/(float)Math.Max(1,data.Columns.Count));for(int c=0;c<data.Columns.Count;c++)e.Graphics.DrawString(data.Columns[c].ColumnName,hf,Brushes.Black,x+c*w,y);y+=20;e.Graphics.DrawLine(pen,x,y,e.MarginBounds.Right,y);y+=4;while(printRow<data.Rows.Count&&y<e.MarginBounds.Bottom-22){for(int c=0;c<data.Columns.Count;c++){string v=Convert.ToString(data.Rows[printRow][c]);if(v.Length>24)v=v.Substring(0,21)+"...";e.Graphics.DrawString(v,bf,Brushes.Black,new RectangleF(x+c*w,y,w-4,18));}y+=20;printRow++;}e.HasMorePages=printRow<data.Rows.Count;}}
  private static void ExportCsv(IWin32Window owner){if(data==null){MessageBox.Show(owner,"Muat data laporan terlebih dahulu.");return;}using(var dlg=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName=reportTitle.Replace(' ','_')+"_"+DateTime.Now.ToString("yyyyMMdd_HHmm")+".csv"}){if(dlg.ShowDialog(owner)!=DialogResult.OK)return;var sb=new StringBuilder();for(int c=0;c<data.Columns.Count;c++){if(c>0)sb.Append(';');sb.Append(EscapeCsv(data.Columns[c].ColumnName));}sb.AppendLine();foreach(DataRow r in data.Rows){for(int c=0;c<data.Columns.Count;c++){if(c>0)sb.Append(';');sb.Append(EscapeCsv(Convert.ToString(r[c])));}sb.AppendLine();}File.WriteAllText(dlg.FileName,sb.ToString(),new UTF8Encoding(true));MessageBox.Show(owner,"CSV berhasil disimpan.","Export",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
  private static string EscapeCsv(string s){return "\""+(s??"").Replace("\"","\"\"")+"\"";}
 }
}
